result.css:
:root{
  --bg:#f7f6f1;
  --ink:#1c302e;
  --accent:#24654d;
  --ink-soft:#3d5350;
  --ink-mute:#566b68;
  --rule:#d8d5c8;
  --rule-soft:#e7e4d9;
  --panel:#f1efe5;
  --tint:#e6eee9;
  --sans:"Apple SD Gothic Neo","Malgun Gothic",system-ui,sans-serif;
  --mono:ui-monospace,SFMono-Regular,"SF Mono",Menlo,Consolas,monospace;
  --measure:62ch;
}

.page,.topbar,.foot{background:var(--bg);color:var(--ink);}
.page *,.topbar *,.foot *{box-sizing:border-box;}

.topbar,.page,.foot{
  font-family:var(--sans);
  word-break:keep-all;
  overflow-wrap:break-word;
  -webkit-text-size-adjust:100%;
}
.page{font-size:16px;line-height:1.7;}

.page h1,.page h2,.page h3,.page h4,
.page p,.page dl,.page dd,.page dt,.page ol,.page ul,.page figure{margin:0;padding:0;}
.page ol,.page ul,.topbar ol{list-style:none;}
.page img{display:block;max-width:100%;height:auto;}
.mono{font-family:var(--mono);font-variant-numeric:tabular-nums;letter-spacing:.06em;}
.mute{color:var(--ink-mute);}

.wrap{width:100%;max-width:1200px;margin:0 auto;padding:0 clamp(20px,5vw,80px);}

/* focus + skip */
.skip{
  position:absolute;left:-9999px;top:0;z-index:50;
  background:var(--accent);color:var(--bg);
  padding:10px 16px;font-family:var(--sans);font-size:14px;text-decoration:none;
}
.skip:focus{left:12px;top:12px;}
a:focus-visible,summary:focus-visible{
  outline:2px solid var(--accent);outline-offset:3px;border-radius:2px;
}

/* ---------- topbar ---------- */
.topbar{
  position:sticky;top:0;z-index:30;
  border-bottom:1px solid var(--rule);
  background:color-mix(in srgb,var(--bg) 92%,transparent);
  backdrop-filter:saturate(120%) blur(6px);
}
.topbar-in{
  display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;
  gap:6px 24px;padding-top:11px;padding-bottom:11px;
}
.mark{display:flex;align-items:baseline;gap:10px;text-decoration:none;color:var(--ink);}
.mark-mono{
  display:inline-block;font-size:12px;font-weight:700;color:var(--accent);
  border:1px solid var(--accent);padding:2px 6px;
}
.mark-text{font-size:14px;font-weight:700;letter-spacing:-.01em;}
.mark-role{font-weight:400;color:var(--ink-mute);font-size:13px;}
.toc ol{display:flex;flex-wrap:wrap;gap:4px 18px;}
.toc a{
  display:inline-flex;align-items:baseline;gap:6px;
  font-size:13.5px;color:var(--ink-soft);text-decoration:none;
  padding:3px 0;border-bottom:1px solid transparent;
  transition:color .2s ease,border-color .2s ease;
}
.toc a i{font-size:10.5px;color:var(--ink-mute);font-style:normal;}
.toc a:hover{color:var(--accent);border-bottom-color:var(--accent);}
.toc a:hover i{color:var(--accent);}

/* ---------- shared bits ---------- */
.link{color:var(--accent);text-decoration:none;border-bottom:1px solid rgba(36,101,77,.35);transition:border-color .2s ease;}
.link:hover{border-bottom-color:var(--accent);}

section[id],article[id],details[id]{scroll-margin-top:96px;}

.band{border-top:1px solid var(--rule);padding:clamp(56px,7vw,104px) 0 clamp(60px,8vw,120px);}
.band-head{
  display:grid;grid-template-columns:minmax(0,1fr);gap:8px;
  margin-bottom:clamp(36px,5vw,64px);
}
.band-num{font-size:12px;color:var(--accent);font-weight:700;}
.band-title{font-size:clamp(28px,4.4vw,44px);line-height:1.15;letter-spacing:-.03em;font-weight:700;}
.band-note{max-width:46ch;color:var(--ink-mute);font-size:15px;}

/* ---------- 01 hero ---------- */
.hero{padding:clamp(40px,6vw,78px) 0 clamp(56px,7vw,96px);}
.hero-grid{display:grid;grid-template-columns:repeat(12,minmax(0,1fr));gap:0 32px;}
.badge{
  grid-column:1/-1;
  display:flex;flex-wrap:wrap;align-items:center;gap:8px 10px;
  font-size:12.5px;color:var(--ink-soft);
  padding-bottom:22px;margin-bottom:clamp(30px,5vw,52px);
  border-bottom:1px solid var(--rule);
}
.badge .mono{
  display:inline-block;font-size:10.5px;font-weight:700;
  color:var(--bg);background:var(--accent);padding:3px 7px;
}
.eyebrow{grid-column:1/-1;font-size:12.5px;color:var(--accent);font-weight:700;margin-bottom:14px;}
.headline{
  grid-column:1/9;
  font-size:clamp(40px,7.6vw,86px);line-height:1.08;letter-spacing:-.045em;font-weight:700;
}
.headline em{font-style:normal;color:var(--accent);position:relative;white-space:nowrap;}
.headline em::after{
  content:"";position:absolute;left:0;right:0;bottom:.06em;height:3px;
  background:var(--accent);opacity:.28;transform-origin:left center;
  animation:draw 1s cubic-bezier(.2,.7,.2,1) .35s both;
}
@keyframes draw{from{transform:scaleX(0);}to{transform:scaleX(1);}}

.hero-side{grid-column:9/13;align-self:end;padding-bottom:6px;}
.lede{font-size:17px;line-height:1.72;color:var(--ink-soft);margin-bottom:26px;}
.hero-meta{border-top:1px solid var(--rule);}
.hero-meta .row{display:grid;grid-template-columns:52px minmax(0,1fr);gap:12px;padding:9px 0;border-bottom:1px solid var(--rule-soft);}
.hero-meta dt{font-size:10.5px;color:var(--ink-mute);padding-top:4px;}
.hero-meta dd{font-size:14.5px;}

.focus{
  grid-column:1/9;margin-top:clamp(40px,5vw,64px);
  display:flex;flex-wrap:wrap;align-items:baseline;gap:10px 30px;
  border-top:1px solid var(--rule);padding-top:18px;
}
.focus-label{font-size:10.5px;color:var(--ink-mute);}
.focus-list{display:flex;flex-wrap:wrap;gap:10px 30px;}
.focus-list li{display:flex;align-items:baseline;gap:8px;font-size:17px;font-weight:600;letter-spacing:-.02em;}
.focus-list .mono{font-size:10.5px;font-weight:400;color:var(--accent);}

.hero-guide{
  grid-column:1/9;margin-top:24px;max-width:56ch;
  font-size:15px;color:var(--ink-mute);
}
.hero-guide strong{color:var(--ink);font-weight:600;}

/* ---------- 02 index ---------- */
.index{border-top:1px solid var(--ink);}
.index-row{
  display:grid;
  grid-template-columns:64px minmax(0,4fr) minmax(0,5fr);
  grid-template-areas:
    "n title sum"
    "n cat meta"
    "n cat tags";
  gap:2px 32px;
  padding:26px 0 28px;
  border-bottom:1px solid var(--rule);
  transition:background-color .25s ease;
}
.index-row:hover{background:color-mix(in srgb,var(--panel) 70%,transparent);}
.index-n{grid-area:n;font-size:11.5px;color:var(--ink-mute);padding-top:8px;}
.index-title{grid-area:title;font-size:clamp(24px,3.2vw,34px);line-height:1.2;letter-spacing:-.035em;font-weight:700;}
.index-title a{
  display:inline-flex;align-items:baseline;gap:10px;
  color:var(--ink);text-decoration:none;
  transition:color .2s ease;
}
.index-title a .arrow{
  font-size:.55em;color:var(--accent);
  transition:transform .25s ease,opacity .25s ease;opacity:.55;
}
.index-title a:hover{color:var(--accent);}
.index-title a:hover .arrow{transform:translateY(4px);opacity:1;}
.index-cat{grid-area:cat;font-size:13.5px;color:var(--accent);margin-top:4px;}
.index-sum{grid-area:sum;font-size:15.5px;color:var(--ink-soft);max-width:48ch;}
.index-meta{grid-area:meta;display:flex;flex-wrap:wrap;align-items:baseline;gap:6px 10px;margin-top:12px;font-size:13.5px;color:var(--ink-mute);}
.index-meta .mono{font-size:12px;}
.index-meta .dot{color:var(--rule);}
.tags{grid-area:tags;display:flex;flex-wrap:wrap;gap:6px;margin-top:10px;}
.tags li{
  font-family:var(--mono);font-size:10.5px;letter-spacing:.04em;
  color:var(--ink-soft);border:1px solid var(--rule);padding:3px 8px;
}

/* ---------- 03 cases ---------- */
.band-cases{padding-bottom:0;}
.case{padding:clamp(44px,5.5vw,76px) 0 clamp(48px,6vw,88px);border-top:1px solid var(--rule);}
.case:first-of-type{border-top:1px solid var(--ink);}
.case-grid{
  display:grid;grid-template-columns:repeat(12,minmax(0,1fr));gap:clamp(28px,3.4vw,44px) 32px;
  align-items:start;
}
.case-head{grid-column:1/5;}
.case-figure{grid-column:5/13;}
.beats{grid-column:5/13;}
.case.flip .case-head{grid-column:9/13;}
.case.flip .case-figure{grid-column:1/9;}
.case.flip .beats{grid-column:1/9;}

.case-tag{font-size:11px;color:var(--accent);font-weight:700;margin-bottom:12px;}
.case-title{font-size:clamp(28px,3.8vw,40px);line-height:1.15;letter-spacing:-.04em;font-weight:700;margin-bottom:14px;}
.case-sum{font-size:15.5px;color:var(--ink-soft);margin-bottom:24px;}
.case-meta{border-top:1px solid var(--rule);}
.case-meta .row{display:grid;grid-template-columns:48px minmax(0,1fr);gap:10px;padding:8px 0;border-bottom:1px solid var(--rule-soft);}
.case-meta dt{font-size:10px;color:var(--ink-mute);padding-top:4px;}
.case-meta dd{font-size:14px;}
.case-meta dd.num{font-size:13px;}

.case-figure{margin:0;}
.case-figure img{
  width:100%;background:var(--panel);
  border:1px solid var(--rule);
  transition:transform .4s cubic-bezier(.2,.7,.2,1);
}
.case-figure:hover img{transform:translateY(-4px);}
.case-figure figcaption{
  margin-top:12px;font-size:12.5px;color:var(--ink-mute);
  padding-left:2px;
}

.beats{display:grid;gap:0;}
.beat{padding:20px 0;border-top:1px solid var(--rule-soft);}
.beat:first-child{border-top:1px solid var(--ink);}
.beat h4{
  display:flex;align-items:baseline;gap:10px;
  font-size:13px;font-weight:700;letter-spacing:.02em;margin-bottom:7px;color:var(--ink);
}
.beat h4 .mono{font-size:10px;font-weight:400;color:var(--ink-mute);}
.beat p{font-size:16px;max-width:var(--measure);color:var(--ink-soft);}
.beat-key{background:var(--tint);padding:20px clamp(16px,2vw,24px);border-top-color:var(--accent);}
.beat-key h4{color:var(--accent);}
.beat-key h4 .mono{color:var(--accent);}
.beat-key p{color:var(--ink);}

.case-ev{
  display:flex;flex-wrap:wrap;align-items:center;gap:8px 12px;
  border-top:1px solid var(--rule-soft);padding-top:18px;margin-top:6px;
}
.ev-label{font-size:10px;color:var(--ink-mute);}
.chip{
  display:inline-block;font-size:13px;color:var(--accent);text-decoration:none;
  border:1px solid rgba(36,101,77,.4);padding:5px 11px;
  transition:background-color .2s ease,color .2s ease;
}
.chip::before{content:"↳ ";opacity:.6;}
.chip:hover{background:var(--accent);color:var(--bg);}

/* ---------- 04 career ---------- */
.career{position:relative;}
.career-item{
  display:grid;grid-template-columns:minmax(0,200px) minmax(0,1fr);gap:8px 40px;
  padding:26px 0 30px;border-top:1px solid var(--rule);position:relative;
}
.career-item:first-child{border-top:1px solid var(--ink);}
.career-item:last-child{border-bottom:1px solid var(--rule);}
.career-period{font-size:12.5px;color:var(--accent);padding-top:6px;position:relative;}
.career-period::before{
  content:"";position:absolute;left:-13px;top:12px;
  width:5px;height:5px;display:block;border-radius:50%;background:var(--accent);
}
.career-role{font-size:clamp(21px,2.6vw,27px);line-height:1.25;letter-spacing:-.03em;font-weight:700;}
.career-org{font-size:14px;color:var(--ink-mute);margin:4px 0 12px;}
.career-desc{font-size:16px;color:var(--ink-soft);max-width:var(--measure);}

/* ---------- 05 evidence ---------- */
.band-evidence{background:linear-gradient(to bottom,var(--panel),var(--panel));}
.ev-group{margin-bottom:clamp(30px,4vw,48px);}
.ev-owner{
  display:flex;align-items:baseline;gap:10px;
  font-size:13px;color:var(--ink-mute);margin-bottom:8px;
}
.ev-owner .link{color:var(--ink);border-bottom-color:var(--rule);font-weight:600;}
.ev-owner .link:hover{color:var(--accent);border-bottom-color:var(--accent);}
.ev-owner .count{font-size:10.5px;color:var(--accent);}

.ev{border-top:1px solid var(--rule);}
.ev:last-child{border-bottom:1px solid var(--rule);}
.ev summary{
  display:grid;
  grid-template-columns:110px minmax(0,1.1fr) minmax(0,1.4fr) 22px;
  gap:6px 24px;align-items:baseline;
  padding:18px 0;cursor:pointer;list-style:none;
  transition:color .2s ease;
}
.ev summary::-webkit-details-marker{display:none;}
.ev-kind{font-size:10.5px;color:var(--accent);padding-top:5px;}
.ev-title{font-size:19px;font-weight:700;letter-spacing:-.025em;}
.ev-sum{font-size:14.5px;color:var(--ink-mute);}
.ev summary::after{
  content:"+";justify-self:end;
  font-family:var(--mono);font-size:17px;color:var(--accent);line-height:1;
  transition:transform .25s ease;
}
.ev[open] summary::after{content:"–";}
.ev summary:hover .ev-title{color:var(--accent);}

.ev-body{
  padding:0 0 26px;max-width:var(--measure);
  animation:reveal .3s ease both;
}
@keyframes reveal{from{opacity:0;transform:translateY(-5px);}to{opacity:1;transform:none;}}
.ev-body p{font-size:15.5px;color:var(--ink-soft);}

.flow{display:flex;flex-wrap:wrap;gap:8px 4px;margin-bottom:16px;}
.flow li{
  display:flex;align-items:center;gap:4px;
  font-size:13.5px;font-weight:600;color:var(--ink);
  background:var(--bg);border:1px solid var(--rule);padding:6px 11px;
}
.flow li:not(:last-child)::after{
  content:"→";display:inline-block;margin-left:7px;margin-right:-4px;
  color:var(--accent);font-family:var(--mono);
}
.checks,.fields{margin-bottom:16px;display:grid;gap:0;}
.checks li,.fields li{
  display:flex;align-items:baseline;gap:10px;
  font-size:15px;padding:8px 0;border-bottom:1px solid var(--rule-soft);
}
.checks li::before{
  content:"";display:block;flex:0 0 auto;
  width:7px;height:7px;background:var(--accent);margin-top:8px;
}
.fields li .mono{font-size:10.5px;color:var(--accent);}

/* ---------- 06 contact ---------- */
.band-contact{border-top:1px solid var(--ink);padding-bottom:clamp(64px,8vw,112px);}
.contact-grid{display:grid;grid-template-columns:repeat(12,minmax(0,1fr));gap:0 32px;}
.contact-grid .band-num{grid-column:1/-1;margin-bottom:18px;}
.contact-head{
  grid-column:1/8;
  font-size:clamp(32px,5.6vw,62px);line-height:1.12;letter-spacing:-.045em;font-weight:700;
}
.contact-side{grid-column:8/13;align-self:end;}
.contact-desc{font-size:15px;color:var(--ink-mute);margin-bottom:12px;max-width:40ch;}
.mailto{
  display:flex;flex-direction:column;gap:4px;
  margin-top:22px;padding:16px 18px;
  background:var(--accent);color:var(--bg);text-decoration:none;
  transition:transform .25s ease,opacity .25s ease;
}
.mailto-label{font-size:10px;opacity:.75;}
.mailto-addr{font-size:clamp(15px,1.6vw,19px);font-weight:700;letter-spacing:-.02em;overflow-wrap:anywhere;}
.mailto:hover{transform:translateY(-2px);opacity:.92;}
.contact-loc{margin-top:16px;font-size:13.5px;color:var(--ink-mute);display:flex;gap:10px;align-items:baseline;}
.contact-loc .mono{font-size:10px;}

/* ---------- footer ---------- */
.foot{border-top:1px solid var(--rule);padding:28px 0 42px;}
.foot-in{display:flex;flex-wrap:wrap;gap:14px 32px;align-items:baseline;justify-content:space-between;}
.foot-note{font-size:12.5px;color:var(--ink-mute);max-width:74ch;line-height:1.65;}
.foot-note .mono{
  display:inline-block;font-size:10px;font-weight:700;color:var(--accent);
  border:1px solid var(--accent);padding:2px 6px;margin-right:6px;
}
.foot-links{font-size:13px;}

/* ---------- tablet ---------- */
@media (max-width:900px){
  .headline{grid-column:1/-1;}
  .hero-side{grid-column:1/-1;margin-top:30px;}
  .lede{max-width:52ch;}
  .focus,.hero-guide{grid-column:1/-1;}

  .case-grid{gap:26px 24px;}
  .case-head{grid-column:1/-1;}
  .case-figure,.beats{grid-column:1/-1;}
  .case.flip .case-head,.case.flip .case-figure,.case.flip .beats{grid-column:1/-1;}

  .contact-head{grid-column:1/-1;}
  .contact-side{grid-column:1/-1;margin-top:28px;}

  .ev summary{grid-template-columns:minmax(0,1fr) 22px;grid-template-areas:"kind mark" "title title" "sum sum";gap:4px 16px;}
  .ev-kind{grid-area:kind;padding-top:0;}
  .ev-title{grid-area:title;}
  .ev-sum{grid-area:sum;}
  .ev summary::after{grid-area:mark;}
}

/* ---------- phone ---------- */
@media (max-width:640px){
  .page{font-size:15.5px;}
  section[id],article[id],details[id]{scroll-margin-top:118px;}
  .topbar-in{padding-top:9px;padding-bottom:9px;gap:6px 14px;}
  .mark-role{display:none;}
  .toc ol{gap:2px 14px;}
  .toc a{font-size:12.5px;}
  .toc a i{display:none;}

  .index-row{
    grid-template-columns:34px minmax(0,1fr);
    grid-template-areas:
      "n title"
      "n cat"
      ". sum"
      ". meta"
      ". tags";
    gap:2px 14px;padding:22px 0 24px;
  }
  .index-n{padding-top:6px;}
  .index-sum{margin-top:10px;}

  .career-item{grid-template-columns:minmax(0,1fr);gap:6px;}
  .career-period::before{display:none;}
  .career-org{margin-bottom:10px;}

  .beat-key{padding-left:14px;padding-right:14px;}
  .flow li{font-size:12.5px;padding:5px 9px;}
  .foot-in{flex-direction:column;align-items:flex-start;}
}

/* ---------- motion ---------- */
@media (prefers-reduced-motion:reduce){
  *{animation:none!important;transition:none!important;}
  .headline em::after{transform:none;}
}
